# Compiles the shaders with fxc and writes their bytecode to Render\Shaders.g.cs
# (ModelExplorer.App.Render.Shaders.<Name> as ReadOnlySpan<byte>, stored in the
# executable's read-only data). The generated file is checked in, so building
# needs only the .NET SDK; this runs when a shader changes and the Windows SDK is
# installed. Skips the work when the output is newer than every source.
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$output = Join-Path (Split-Path $root -Parent) 'Render\Shaders.g.cs'

# file, entry point, profile, generated member
$shaders = @(
    @('mesh.hlsl', 'vs_main', 'vs_5_0', 'MeshVs'),
    @('mesh.hlsl', 'ps_main', 'ps_5_0', 'MeshPs'),
    @('mesh.hlsl', 'ps_overlay', 'ps_5_0', 'MeshOverlayPs'),
    @('line.hlsl', 'vs_main', 'vs_5_0', 'LineVs'),
    @('line.hlsl', 'ps_main', 'ps_5_0', 'LinePs'),
    @('composite.hlsl', 'vs_fullscreen', 'vs_5_0', 'CompositeVs'),
    @('composite.hlsl', 'ps_composite', 'ps_5_0', 'CompositePs')
)

$sources = Get-ChildItem $root -File | Where-Object { $_.Extension -in '.hlsl', '.hlsli', '.ps1' }
if ((Test-Path $output) -and -not ($sources | Where-Object { $_.LastWriteTimeUtc -gt (Get-Item $output).LastWriteTimeUtc })) { return }

$fxc = Get-ChildItem "${env:ProgramFiles(x86)}\Windows Kits\10\bin\*\x64\fxc.exe" -ErrorAction SilentlyContinue |
    Sort-Object { [version]$_.Directory.Parent.Name } | Select-Object -Last 1
if (-not $fxc) {
    if (Test-Path $output) {
        Write-Warning 'fxc.exe not found (Windows SDK); using the checked-in compiled shaders.'
        return
    }
    throw 'fxc.exe not found; install the Windows SDK to compile the shaders.'
}

$temporary = Join-Path ([IO.Path]::GetTempPath()) ("me-shaders-" + [Guid]::NewGuid())
New-Item -ItemType Directory -Force $temporary | Out-Null
try {
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine('// <auto-generated> by Shaders\build.ps1 from the .hlsl files beside it. Do not edit. </auto-generated>')
    [void]$sb.AppendLine('namespace ModelExplorer.App.Render;')
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('internal static class Shaders')
    [void]$sb.AppendLine('{')
    foreach ($s in $shaders) {
        $file, $entry, $profile, $name = $s
        $cso = Join-Path $temporary "$name.cso"
        & $fxc.FullName /nologo /O3 /T $profile /E $entry /Fo $cso (Join-Path $root $file) | Out-Null
        if ($LASTEXITCODE) { throw "fxc failed for $file $entry" }
        $bytes = [IO.File]::ReadAllBytes($cso)
        [void]$sb.Append("    public static System.ReadOnlySpan<byte> $name => [")
        [void]$sb.Append(($bytes -join ','))
        [void]$sb.AppendLine('];')
    }
    [void]$sb.AppendLine('}')
    [IO.File]::WriteAllText($output, $sb.ToString())
}
finally {
    Remove-Item -Recurse -Force $temporary -ErrorAction SilentlyContinue
}
